interface MuxUICollectionItem {
  id?: string;
  key?: string;
  label?: React.ReactNode;
  value?: string;
  textValue?: string;
  disabled?: boolean;
  [key: string]: unknown;
}

interface FieldValidationProps {
  description?: React.ReactNode;
  errorMessage?: React.ReactNode;
  disabled?: boolean;
  readOnly?: boolean;
  required?: boolean;
  invalid?: boolean;
  size?: ControlSize;
  className?: string;
}

type MuxUIAccessibleName = {
  label: Exclude<React.ReactNode, null | undefined | boolean>;
  'aria-label'?: never;
  'aria-labelledby'?: never;
} | {
  label?: never;
  'aria-label': string;
  'aria-labelledby'?: never;
} | {
  label?: never;
  'aria-label'?: never;
  'aria-labelledby': string;
};

type SelectItemOwnProps = {
  id: string;
  textValue?: string;
  disabled?: boolean;
};

type SelectOptions = Omit<SelectOwnProps, 'label' | 'description' | 'errorMessage'> & {
  anchorRef?: React.RefObject<Element | null>;
};

type SelectOwnProps = {
  label?: Exclude<React.ReactNode, null | undefined | boolean>;
  description?: React.ReactNode;
  errorMessage?: React.ReactNode;
  items?: MuxUIItems;
  value?: string;
  defaultValue?: string;
  open?: boolean;
  defaultOpen?: boolean;
  disabled?: boolean;
  size?: 'sm' | 'md' | 'lg';
  readOnly?: boolean;
  required?: boolean;
  invalid?: boolean;
  name?: string;
  placeholder?: string;
  children?: React.ReactNode;
  selectedContent?: React.ReactNode;
  trigger?: React.ReactElement<React.DetailedHTMLProps<React.ButtonHTMLAttributes<HTMLButtonElement>, HTMLButtonElement>, 'button'>;
  placement?: MuxUIPlacement;
  offset?: number;
  crossOffset?: number;
  shouldFlip?: boolean;
  containerPadding?: number;
  modal?: boolean;
  onChange?: (value?: string) => void;
  onOpenChange?: (open: boolean) => void;
};

type SelectPopupOwnProps = {
  placement?: MuxUIPlacement;
  offset?: number;
  crossOffset?: number;
  shouldFlip?: boolean;
  containerPadding?: number;
  modal?: boolean;
};

type SelectPopupProps = React.HTMLAttributes<HTMLDivElement> & SelectPopupOwnProps & {
  anchorRef?: React.RefObject<Element | null>;
};
